listing = repo.list("src")
loose = repo.search("FIX\\s*-?\\s*ME", glob = "src/**")
case_insensitive = repo.search("(?i)fixme", glob = "src/**")
files = {}
for h in loose:
    files.setdefault(h.path, []).append(h.text.strip())
contents = {}
for entry in listing:
    if entry.endswith("/"):
        sub = repo.list("src/" + entry.rstrip("/"))
        for s in sub:
            contents["src/" + entry.rstrip("/") + "/" + s] = repo.read("src/" + entry.rstrip("/") + "/" + s, missing_ok=True)
    else:
        contents["src/" + entry] = repo.read("src/" + entry, missing_ok=True)
return {
    "listing": listing,
    "loose_matches": files,
    "case_insensitive_count": len(case_insensitive),
    "contents": {k: v for k, v in contents.items()},
}
